class NestedIterator {
  constructor(nested) {
    this.stack = [[nested, 0]]
  }

  hasNext() {
    while (this.stack.length > 0) {
      const top = this.stack[this.stack.length - 1]
      const [list, i] = top
      if (i === list.length) {
        this.stack.pop()
      } else if (Array.isArray(list[i])) {
        top[1] = i + 1
        this.stack.push([list[i], 0])
      } else {
        return true
      }
    }
    return false
  }

  next() {
    this.hasNext()
    const top = this.stack[this.stack.length - 1]
    return top[0][top[1]++]
  }
}

function runNestedIterator(nested, ops) {
  const it = new NestedIterator(nested)
  return ops.map(op => (op === 'next' ? it.next() : it.hasNext()))
}

