class NestedIterator:
    def __init__(self, nested):
        self.stack = [[nested, 0]]

    def has_next(self):
        while self.stack:
            top = self.stack[-1]
            items, i = top
            if i == len(items):
                self.stack.pop()
            elif isinstance(items[i], list):
                top[1] = i + 1
                self.stack.append([items[i], 0])
            else:
                return True
        return False

    def next(self):
        self.has_next()
        top = self.stack[-1]
        value = top[0][top[1]]
        top[1] += 1
        return value


def run_nested_iterator(nested, ops):
    it = NestedIterator(nested)
    return [it.next() if op == "next" else it.has_next() for op in ops]
